// How well the community loop groups what the club asks for, and how often its drafts are refused.
// Simulated club: members and requests generated by code (test/sim/loop_club.mjs). The paraphrases, the embeddings, the
// grouping, the drafts and the review are real.
//   1. For each seed, the club's requests (all but the three hostile ideas, which the screen stops; the two poisoned
//      items stay) are paraphrased once by Muse Glimmer, sentence and topic, and kept (data/loop_cluster/seed-<n>.json).
//   2. DRAMA embeds the sentences and the topics. Each way of grouping is scored against the idea every request came
//      from, which only the simulation knows: homogeneity (each group is one idea), completeness (each idea is one
//      group), V-measure, adjusted Rand index, groups that mix ideas, and what matters for the loop: how many ideas
//      surface as one group of 5 or more members (80% of it one idea), and how many groups of 5 or more mix ideas.
//      The threshold is chosen on the first seed and reported on the others.
//   3. The drafter, as it was (no never-list) and as it is (the never-list shown, the files checked by code), a few
//      times per idea that the grouping surfaces, each draft through the review: how often a draft is refused.
//   LLM_URL=http://127.0.0.1:11446/v1 LLM_SLOTS=8 node test/loop_cluster_eval.mjs [data/loop_cluster_eval.json] [--seeds 7,11,13] [--drafts 3] [--fresh]
import fs from "node:fs";
import path from "node:path";
import os from "node:os";

const args = process.argv.slice(2), opt = (k, d) => { const i = args.indexOf(k); return i >= 0 ? args[i + 1] : d; };
const OUT = args.find((a) => !a.startsWith("--") && !/^\d/.test(a) && /\.json$/.test(a)) || "data/loop_cluster_eval.json";
const SEEDS = opt("--seeds", "7,11,13").split(",").map(Number), DRAFTS = +opt("--drafts", 3), FRESH = args.includes("--fresh");
const CACHE = path.resolve("data/loop_cluster"), tmp = fs.mkdtempSync(path.join(os.tmpdir(), "serve-cluster-"));
fs.mkdirSync(CACHE, { recursive: true });
Object.assign(process.env, { LOOP_DIR: `${tmp}/loop`, STORE_FILE: `${tmp}/players.json`, LEDGER_FILE: `${tmp}/ledger.jsonl`, TRACE_FILE: `${tmp}/traces.jsonl`, MEMORY_FILE: `${tmp}/memory.json`, LOOP_SIMULATED: "1" });
process.env.REEL_HF_CACHE ||= "/mnt/nas/shuttlecoach-meta/hf";
process.env.HF_HUB_OFFLINE ||= "1";
const { rng, simClub } = await import("./sim/loop_club.mjs");
const signals = await import("../src/loop/signals.js");
const proposals = await import("../src/loop/proposals.js");
const memory = await import("../src/memory.js");
const ledger = await import("../src/ledger.js");
const { load } = await import("../src/loop/parts.js");
const { review } = await load();
const T0 = Date.UTC(2026, 8, 7, 4, 0), SLOTS = Math.max(1, +(process.env.LLM_SLOTS || 4)), t00 = Date.now();
const pool = async (xs, fn) => { const out = new Array(xs.length); let next = 0; await Promise.all(Array.from({ length: Math.min(SLOTS, xs.length) }, async () => { while (next < xs.length) { const i = next++; out[i] = await fn(xs[i], i); } })); return out; };

// ---- 1. the requests, paraphrased once per seed ----
async function itemsOf(seed) {
  const file = path.join(CACHE, `seed-${seed}.json`);
  if (!FRESH && fs.existsSync(file)) return JSON.parse(fs.readFileSync(file, "utf8"));
  const { supports } = simClub({ seed, members: 60, R: rng(seed * 7919 + 1), T0 });
  const asked = supports.filter((s) => !s.hostile || s.idea === "poison");
  const got = await pool(asked, async (s, i) => { const r = await signals.paraphrase(s.text); return r.ok ? { id: `I-${seed}-${i}`, idea: s.idea, who: s.p.id, group: s.p.group, kind: s.kind, at: s.at, raw: s.text, text: r.text, area: r.area || "other", aspect: r.aspect || "other", topic: r.topic || null } : { idea: s.idea, raw: s.text, refused: r.why }; });
  fs.writeFileSync(file, JSON.stringify(got, null, 1));
  return got;
}

// ---- 2. scores against the ideas ----
const C2 = (n) => (n * (n - 1)) / 2;
function score(items, groups) {
  const idea = new Map(items.map((x) => [x.id, x.idea])), who = new Map(items.map((x) => [x.id, x.who])), N = items.length;
  const ideas = [...new Set(items.map((x) => x.idea))], cnt = groups.map((g) => { const m = new Map(); for (const id of g) m.set(idea.get(id), (m.get(idea.get(id)) || 0) + 1); return m; });
  const H = (ps) => -ps.filter((p) => p > 0).reduce((s, p) => s + p * Math.log(p), 0);
  const nIdea = new Map(ideas.map((k) => [k, items.filter((x) => x.idea === k).length]));
  const HC = H(ideas.map((k) => nIdea.get(k) / N)), HK = H(groups.map((g) => g.length / N));
  let HCK = 0, HKC = 0;
  groups.forEach((g, gi) => { for (const [k, n] of cnt[gi]) { HCK -= (n / N) * Math.log(n / g.length); HKC -= (n / N) * Math.log(n / nIdea.get(k)); } });
  const homogeneity = HC ? 1 - HCK / HC : 1, completeness = HK ? 1 - HKC / HK : 1, v = homogeneity + completeness ? (2 * homogeneity * completeness) / (homogeneity + completeness) : 0;
  const sumPairs = cnt.reduce((s, m) => s + [...m.values()].reduce((t, n) => t + C2(n), 0), 0), a = groups.reduce((s, g) => s + C2(g.length), 0), b = ideas.reduce((s, k) => s + C2(nIdea.get(k)), 0), e = (a * b) / C2(N);
  const ari = (a + b) / 2 - e ? (sumPairs - e) / ((a + b) / 2 - e) : 1;
  const members = (g, k = null) => new Set(g.filter((id) => k == null || idea.get(id) === k).map((id) => who.get(id))).size;
  const majority = (gi) => [...cnt[gi].entries()].sort((p, q) => q[1] - p[1])[0];
  const big = groups.map((g, gi) => ({ gi, m: members(g) })).filter((x) => x.m >= 5);
  const surfaced = ideas.filter((k) => groups.some((g, gi) => { const [mk, mn] = majority(gi); return mk === k && mn / g.length >= 0.8 && members(g, k) >= 5; }));
  const reachable = ideas.filter((k) => new Set(items.filter((x) => x.idea === k).map((x) => x.who)).size >= 5);
  return { groups: groups.length, homogeneity: +homogeneity.toFixed(3), completeness: +completeness.toFixed(3), vMeasure: +v.toFixed(3), ari: +ari.toFixed(3),
    mixed: groups.filter((g, gi) => cnt[gi].size > 1).length, mixedBig: big.filter(({ gi }) => majority(gi)[1] / groups[gi].length < 0.8).length,
    surfaced: surfaced.length, reachable: reachable.length, missed: reachable.filter((k) => !surfaced.includes(k)),
    perIdea: Object.fromEntries(ideas.map((k) => [k, { groups: groups.filter((g) => g.some((id) => idea.get(id) === k)).length, largestShare: +(Math.max(...groups.map((g) => g.filter((id) => idea.get(id) === k).length)) / nIdea.get(k)).toFixed(2) }])) };
}

// ---- the ways of grouping ----
const LINKS = [0.7, 0.74, 0.78, 0.8, 0.82, 0.85, 0.88, 0.9];
const WAYS = [
  { name: "first version: greedy on the sentence (0.80 same aspect, 0.85 otherwise)", how: "greedy", on: "text" },
  { name: "greedy on the topic", how: "greedy", on: "topic" },
  ...LINKS.map((t) => ({ name: `average linkage on the sentence, ${t}`, how: "average", on: "text", link: t })),
  ...LINKS.map((t) => ({ name: `average linkage on the topic, ${t}`, how: "average", on: "topic", link: t })),
  ...LINKS.map((t) => ({ name: `average linkage on sentence and topic, ${t}`, how: "average", on: "both", link: t })),
];
const out = { label: "Simulated club: members and requests generated by code. The paraphrases, embeddings, grouping, drafts and review are real.", at: new Date().toISOString(), endpoint: process.env.LLM_URL || "http://127.0.0.1:11435/v1", seeds: SEEDS, seedsData: {}, ways: {}, chosen: null, drafts: {} };
const vectors = {};
for (const seed of SEEDS) {
  const all = await itemsOf(seed), items = all.filter((x) => x.id);
  const vt = await memory.embed(items.map((x) => x.text)), vp = await memory.embed(items.map((x) => x.topic || x.text));
  if (!vt || !vp) throw new Error("DRAMA is not running");
  const norm = (v) => { const n = Math.hypot(...v) || 1; return v.map((x) => x / n); };
  vectors[seed] = { text: new Map(items.map((x, i) => [x.id, vt[i]])), topic: new Map(items.map((x, i) => [x.id, vp[i]])), both: new Map(items.map((x, i) => [x.id, norm(vt[i].map((a, d) => a + vp[i][d]))])) };
  out.seedsData[seed] = { requests: all.length, paraphrased: items.length, refused: all.filter((x) => !x.id).map((x) => x.refused), withTopic: items.filter((x) => x.topic).length, ideas: Object.fromEntries([...new Set(items.map((x) => x.idea))].map((k) => [k, { items: items.filter((x) => x.idea === k).length, members: new Set(items.filter((x) => x.idea === k).map((x) => x.who)).size }])),
    examples: items.slice(0, 12).map((x) => ({ idea: x.idea, text: x.text, topic: x.topic, area: x.area, aspect: x.aspect })) };
  for (const w of WAYS) {
    const vec = (id) => vectors[seed][w.on].get(id);
    (out.ways[w.name] ||= { ...w, seeds: {} }).seeds[seed] = score(items, proposals.group(items, vec, { how: w.how, link: w.link }));
  }
  console.log(`seed ${seed}: ${items.length} requests paraphrased`);
}
// and each of the better ways followed by the model's merge (proposals.mergeSame: Muse Glimmer names the groups of one
// part of the app that ask for the same change; code merges them when their centres are at the floor or more)
const BASES = [WAYS[0], WAYS.find((w) => w.how === "average" && w.on === "text" && w.link === 0.85), WAYS.find((w) => w.how === "average" && w.on === "topic" && w.link === 0.82)];
for (const seed of SEEDS) {
  const items = (await itemsOf(seed)).filter((x) => x.id), byId = new Map(items.map((x) => [x.id, x]));
  for (const base of BASES) {
    const vec = (id) => vectors[seed][base.on].get(id), groups = proposals.group(items, vec, { how: base.how, link: base.link }), areas = [...new Set(groups.map((g) => byId.get(g[0]).area))];
    const answers = new Map();
    await pool(areas, async (a) => { const gs = groups.filter((g) => byId.get(g[0]).area === a); answers.set(a, { gs, pairs: await proposals.sameChange(gs.map((g) => g.map((id) => byId.get(id).text))).catch(() => []) }); });
    for (const floor of [0.6, 0.65, 0.7, 0.75]) {
      const merged = [];
      for (const { gs, pairs } of answers.values()) merged.push(...(await proposals.mergeSame(gs, { text: (id) => byId.get(id).text, vec, whoOf: (id) => byId.get(id)?.who, floor, ask: async () => pairs })));
      const name = `${base.name}, then the model's merge at ${floor}`;
      (out.ways[name] ||= { name, how: base.how, on: base.on, link: base.link ?? null, merge: floor, seeds: {} }).seeds[seed] = score(items, merged);
    }
  }
}
// the way chosen on the first seed (the most ideas surfaced, then the fewest big groups that mix, then V-measure), as reported on the others
const dev = SEEDS[0], rankBy = (s) => [s.surfaced, -s.mixedBig, s.vMeasure];
const order = Object.values(out.ways).sort((a, b) => { const x = rankBy(a.seeds[dev]), y = rankBy(b.seeds[dev]); for (let i = 0; i < x.length; i++) if (x[i] !== y[i]) return y[i] - x[i]; return 0; });
out.chosen = { on: dev, name: order[0].name, how: order[0].how, embedOn: order[0].on, link: order[0].link ?? null };
const first = out.ways[WAYS[0].name];
out.summary = SEEDS.map((seed) => ({ seed, first: first.seeds[seed], chosen: out.ways[out.chosen.name].seeds[seed] }));
console.log(JSON.stringify(out.summary.map((x) => ({ seed: x.seed, first: { surfaced: x.first.surfaced, reachable: x.first.reachable, mixedBig: x.first.mixedBig, v: x.first.vMeasure, groups: x.first.groups }, chosen: { surfaced: x.chosen.surfaced, mixedBig: x.chosen.mixedBig, v: x.chosen.vMeasure, groups: x.chosen.groups } })), null, 1), `chosen: ${out.chosen.name}`);

// ---- 3. the drafter, before and after the never-list check ----
for (const seed of DRAFTS > 0 ? SEEDS : []) {
  const items = (await itemsOf(seed)).filter((x) => x.id), vec = (id) => vectors[seed][out.chosen.embedOn].get(id);
  const groups = proposals.group(items, vec, { how: out.chosen.how, link: out.chosen.link ?? undefined }), byId = new Map(items.map((x) => [x.id, x]));
  const eligible = groups.map((g) => g.map((id) => byId.get(id))).filter((g) => new Set(g.map((x) => x.who)).size >= 5 && new Set(g.map((x) => x.group)).size === 2);
  const rows = [];
  await pool(eligible, async (g, gi) => {
    const sum = await proposals.summarize(g.map((x) => x.text));
    if (!sum.ok) { rows.push({ cluster: gi, error: sum.why }); return; }
    const who = new Map(); for (const x of g) who.set(x.who, who.get(x.who) === "unmet" || x.kind === "unmet" ? "unmet" : "wish");
    const unmet = [...who.values()].filter((k) => k === "unmet").length, cl = { id: `C-${seed}-${gi}`, members: who.size, unmet, wishes: who.size - unmet, groups: ["weekday", "weekend"] };
    const ideaOf = (() => { const c = new Map(); for (const x of g) c.set(x.idea, (c.get(x.idea) || 0) + 1); return [...c.entries()].sort((p, q) => q[1] - p[1])[0][0]; })();
    for (const constrain of [false, true]) for (let k = 0; k < DRAFTS; k++) {
      const r = await proposals.draftSpec(cl, sum, { constrain, id: `P-9${seed}${gi}${k}${constrain ? 1 : 0}` });
      if (r.error) { rows.push({ cluster: gi, idea: ideaOf, constrain, error: r.error }); continue; }
      const v = review.check(r.spec, null, {}), paths = v.gates?.find((x) => x.gate === "paths");
      rows.push({ cluster: gi, idea: ideaOf, constrain, class: r.spec.change.class, kind: r.spec.change.kind, files: r.spec.change.files, blocked: r.spec.change.blocked?.map((x) => x.file) || [], needs: v.needs, refusedByPaths: paths?.ok === false, reasons: v.reasons.slice(0, 3) });
    }
  });
  const of = (c) => rows.filter((r) => r.constrain === c && !r.error);
  out.drafts[seed] = { clusters: eligible.length, rows, before: { drafts: of(false).length, refused: of(false).filter((r) => r.needs === "never").length, refusedByPaths: of(false).filter((r) => r.refusedByPaths).length },
    after: { drafts: of(true).length, refused: of(true).filter((r) => r.needs === "never").length, refusedByPaths: of(true).filter((r) => r.refusedByPaths).length, blockedToMaintainer: of(true).filter((r) => r.blocked.length).length } };
  console.log(`seed ${seed} drafts: before ${JSON.stringify(out.drafts[seed].before)}, after ${JSON.stringify(out.drafts[seed].after)}`);
}
const tot = (k) => SEEDS.filter((s) => out.drafts[s]).reduce((a, s) => { for (const [x, n] of Object.entries(out.drafts[s][k])) a[x] = (a[x] || 0) + n; return a; }, {});
out.draftsTotal = { before: tot("before"), after: tot("after") };
const calls = {}; for (const c of ledger.calls(100000)) { if (!/^loop\./.test(c.site || "")) continue; (calls[c.site] ||= []).push(c.seconds || 0); }
out.calls = Object.fromEntries(Object.entries(calls).map(([k, v]) => { v.sort((a, b) => a - b); return [k, { calls: v.length, p50: +v[Math.floor(v.length / 2)].toFixed(1), p95: +v[Math.min(v.length - 1, Math.ceil(0.95 * v.length) - 1)].toFixed(1) }]; }));
out.seconds = Math.round((Date.now() - t00) / 1000);
fs.writeFileSync(OUT, JSON.stringify(out, null, 1));
console.log(JSON.stringify(out.draftsTotal), `\nwritten ${OUT}`);
memory.close(); process.exit(0);
